-- Інструменти Саші для креативів: Claude + Midjourney + Higgsfield + CapCut → у «Чим робимо креативи» і шаблони стилю.
INSERT INTO settings (key, value) VALUES ('creative.tools', 'Claude (ідея, тексти, статика, моушен), Midjourney (фото), Higgsfield (оживити фото у відео), CapCut (монтаж, субтитри)')
  ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now');

INSERT INTO creative_styles (kind, title, body, source) VALUES
('general', 'Мій конвеєр: Claude → Midjourney → Higgsfield → CapCut', '- Claude: кут, хук, тексти, сценарій покадрово, статика і моушен (HTML), промпти для інших інструментів.
- Midjourney: ключові кадри / фото обʼєкта і людей (без тексту в кадрі).
- Higgsfield: оживити кадр з Midjourney у відео 5–8 с (image → video), один рух камери на кадр.
- CapCut: зібрати ролик 9:16, субтитри, голос, музика, фінальний CTA-кадр.
- Для відео давай ОДРАЗУ все: сценарій по секундах + промпт Midjourney на кожен кадр + промпт Higgsfield (рух камери) + інструкцію монтажу в CapCut.', 'seed'),
('imagegen', 'Midjourney: як писати промпти', '- Англійською, порядок: обʼєкт/сцена → деталі → композиція і ракурс → світло → обʼєктив/камера → стиль/настрій.
- Співвідношення: --ar 4:5 (стрічка) або --ar 9:16 (Reels/Stories, кадри для Higgsfield).
- Єдиний стиль клієнта: --sref <код або URL референсу> (код зберігай у «Бренді» клієнта); той самий продукт/обʼєкт у різних сценах: --oref <URL> (сила — --ow).
- Текст у кадрі НЕ генерувати — залишати чисте місце під заголовок (вгорі або внизу), напиши де саме.
- 3 варіанти промпту на кадр: різний ракурс/світло, решта однакове.
- Версію моделі не вказуй — бери поточну за замовчуванням.', 'seed'),
('video', 'Higgsfield: оживлення кадрів', '- Вхід — кадр з Midjourney 9:16; на виході 5–8 с на кадр, потім склеїти в CapCut.
- Один рух камери на кадр, назвою пресету: dolly in, orbit, crane up, crash zoom, FPV — і що саме рухається в сцені.
- Перша секунда — найсильніший рух або зміна (хук); кінець кадру спокійний — під склейку.
- Для однієї людини в кількох кадрах — та сама фотографія-референс (консистентність облич ще неідеальна, перевіряй).
- Дорогі моделі = більше кредитів: спершу тест на дешевшій, фінал — на найкращій.', 'seed'),
('video', 'CapCut: монтаж під Meta', '- Проєкт 9:16, 1080×1920; ролик 15–30 с; перші 1–2 с — хук (текст + рух).
- Субтитри автоматично, але ПЕРЕВІРЯЙ кожен рядок; великі, по 2–4 слова, у безпечній зоні (не в нижніх ~340 px).
- Озвучка: свій голос або AI-голос; музика тихо під голосом.
- Останні 2–3 с — CTA-кадр (що зробити + оффер).
- Для реклами — тільки Pro-акаунт і музика/шаблони з позначкою комерційного використання (умови CapCut мінялись — перевіряй ліцензію кожного елемента).', 'seed');

INSERT INTO changelog (title, body, created_at) VALUES ('Креативи: Midjourney, Higgsfield, CapCut у стилі', 'У «Креативи → Мій стиль» вписано твої інструменти (Claude, Midjourney, Higgsfield, CapCut) і 4 нові шаблони: конвеєр Claude → Midjourney → Higgsfield → CapCut, як писати промпти Midjourney (--ar, --sref для стилю клієнта, --oref для одного продукту в різних сценах, без тексту в кадрі), оживлення кадрів у Higgsfield (один рух камери на кадр), монтаж у CapCut під Meta (9:16, субтитри перевіряти, комерційна ліцензія музики). Тепер промпти на відео й фото Джері пише одразу під ці інструменти. Порада: код --sref клієнта впиши в його «Бренд».', datetime('now'));
